let results = [];

for (let item of items) {
    if (item.binary) {
        // If there's binary data in the item, process each binary file
        for (let key in item.binary) {
            // Use the key as the file name
            let binaryKey = key.replace(/\s/g, '_'); // Replace spaces with underscores for the key
            results.push({
                json: {
                    fileName: binaryKey
                },
                binary: {
                    [binaryKey]: item.binary[key] // Use the modified key for the binary data
                }
            });
        }
    }
}

return results;

const preguntas = items.map(i => i.json.pregunta);

const frecuencias = {};

for (const p of preguntas) {
  if (!frecuencias[p]) frecuencias[p] = 0;
  frecuencias[p]++;
}

// Transformar a lista ordenada
const resultado = Object.entries(frecuencias)
  .map(([pregunta, repeticiones]) => ({ pregunta, repeticiones }))
  .sort((a, b) => b.repeticiones - a.repeticiones)
  .slice(0, 20);

return resultado.map(r => ({ json: r }));

const inputData = $input.all();

return inputData.map(item => {
  return {
    json: {
      answer: item.json.answer
        .replace(/\n/g, ' ')  // Reemplaza saltos de línea por espacios
        .replace(/\r/g, '')   // Elimina retornos de carro
        .replace(/\t/g, ' ')  // Reemplaza tabulaciones por espacios
        .replace(/[\x00-\x1F\x7F]/g, '') // Elimina otros caracteres de control
    }
  };
});

const inputData = $input.all();

return inputData.map(item => {
  return {
    json: {
      answer: item.json.respuesta
        .replace(/\n/g, ' ')  // Reemplaza saltos de línea por espacios
        .replace(/\r/g, '')   // Elimina retornos de carro
        .replace(/\t/g, ' ')  // Reemplaza tabulaciones por espacios
        .replace(/[\x00-\x1F\x7F]/g, '') // Elimina otros caracteres de control
    }
  };
});

const userQuery = $input.first().json.chatInput;
const stopwords = [
  'el', 'la', 'de', 'que', 'y', 'a', 'en', 'un', 'ser', 'se', 'no',
  'haber', 'por', 'con', 'su', 'para', 'como', 'estar', 'tener',
  'le', 'lo', 'todo', 'pero', 'más', 'hacer', 'o', 'poder', 'decir',
  'este', 'ir', 'otro', 'ese', 'si', 'me', 'ya', 'ver', 'porque',
  'dar', 'cuando', 'él', 'muy', 'sin', 'vez', 'mucho', 'saber',
  'qué', 'sobre', 'mi', 'alguno', 'mismo', 'yo', 'también', 'hasta'
];

// Extraer palabras significativas
const words = $input.first().json.body.prompt
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^\w\s]/g, '')
  .split(/\s+/)
  .filter(word => word.length > 3 && !stopwords.includes(word));

const keywordsArray = [...new Set(words)];
const keywords = JSON.stringify(keywordsArray); // Convertir a string formato JSON

// Detectar si menciona un archivo PDF
const pdfMention = $input.first().json.body.prompt.match(/(\w+)\.pdf/i);
const filenameFilter = pdfMention ? pdfMention[0] : null;

// Construir filtro dinámico
let metadataFilter = {};

if (keywordsArray.length > 0 && filenameFilter) {
  // Si hay keywords Y filename
  metadataFilter = {
    $and: [
      { "Filename": { $contains: filenameFilter } },
      {
        $or: keywordsArray.map(kw => ({
          "palabras claves": { $contains: kw }
        }))
      }
    ]
  };
} else if (filenameFilter) {
  // Solo filename
  metadataFilter = {
    "Filename": { $contains: filenameFilter }
  };
} else if (keywordsArray.length > 0) {
  // Solo keywords
  metadataFilter = {
    $or: keywordsArray.map(kw => ({
      "palabras claves": { $contains: kw }
    }))
  };
}

return {
  json: {
    query: userQuery,
    keywords: keywords, // Ahora es un string: "[\"palabra1\",\"palabra2\"]"
    filename: filenameFilter,
    metadataFilter: Object.keys(metadataFilter).length > 0 ? metadataFilter : null,
    hasFilter: Object.keys(metadataFilter).length > 0
  }
};
